import generated from './readerLanguages.generated.json';
import part1 from './readerLanguages.part1.generated.json';
import part2 from './readerLanguages.part2.generated.json';
import { BIBLE_EDITIONS } from './bibleEditions';

export interface ReaderLanguageProfile {
  aliases: Record<string, { book: string; evidence: string }[]>;
  scripts: string[];
  words: string;
  grams: string;
  corpus: { folders: string[]; rows: number; sha256: string };
  readiness: { lessonEntries: number; dictionaryEntries: number };
  unresolvedSourceAliases: string[];
}

// Preserve manifest order as well as every profile when joining the build chunks.
const profiles: Record<string, ReaderLanguageProfile> = { ...part1, ...part2 };
export const readerLanguages: Readonly<Record<string, ReaderLanguageProfile>> = Object.fromEntries(
  generated.locales.map((locale) => [locale, profiles[locale]]),
);
export const languageEditions = (locale: string) =>
  BIBLE_EDITIONS.filter((edition) => edition.locale === locale);

/** Keep Indic vowel marks and Latin accents; normalize Arabic optional reading marks. */
export const normalizeReaderText = (value: string): string =>
  value
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[\u064b-\u065f\u0670]/g, '');

export const normalizeReaderAlias = (value: string): string =>
  normalizeReaderText(value)
    .normalize('NFD')
    .replace(/([\p{Script=Latin}\p{Script=Greek}])\p{M}+/gu, '$1')
    .normalize('NFC')
    .replace(/[\s.~\p{Cf}]/gu, '');

const digitZeros = [
  0x0030, 0x0660, 0x06f0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66, 0x0be6, 0x0c66, 0x0ce6, 0x0d66,
  0x0e50, 0x0ed0, 0x0f20, 0x1040, 0x1090, 0x17e0, 0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50,
  0x1bb0, 0x1c40, 0x1c50, 0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0, 0xff10,
];
export const normalizeReaderDigits = (value: string): string =>
  [...value.normalize('NFKC')]
    .map((character) => {
      const point = character.codePointAt(0) || 0;
      const zero = digitZeros.find((start) => point >= start && point < start + 10);
      return zero === undefined ? character : String(point - zero);
    })
    .join('');

type PreparedProfile = {
  words: Set<string>;
  grams: Map<string, number>;
  scripts: RegExp[];
  characters: Set<string>;
};
let prepared: Record<string, PreparedProfile> | undefined;
const prepare = () => {
  if (!prepared) {
    prepared = Object.fromEntries(
      Object.entries(readerLanguages).map(([locale, profile]) => [
        locale,
        {
          words: new Set(profile.words.split('|')),
          characters: new Set([...profile.grams].filter((character) => /\p{L}/u.test(character))),
          grams: new Map(profile.grams.split('|').map((gram, index) => [gram, index + 1])),
          scripts: profile.scripts.map((script) => new RegExp(`\\p{Script=${script}}`, 'u')),
        },
      ]),
    );
  }
  return prepared;
};

export interface LanguageEvidence {
  locale: string;
  reason: 'script' | 'vocabulary' | 'corpus';
  score: number;
}

/** Candidates, not a forced guess. Context may resolve ties only after evidence is evaluated. */
export function detectReaderLanguages(input: string): LanguageEvidence[] {
  const text = normalizeReaderText(input);
  const tokens = text.match(/[\p{L}\p{M}]+/gu) || [];
  const letters = [...text].filter((character) => /\p{L}/u.test(character));
  if (!letters.length) {
    return [];
  }
  const compatible = Object.entries(prepare()).filter(([, profile]) =>
    letters.every((character) => profile.scripts.some((script) => script.test(character))),
  );
  if (compatible.length === 1) {
    return [{ locale: compatible[0][0], reason: 'script', score: 1 }];
  }
  // Shared Unicode scripts can have corpus-backed distinguishing letters. Do not
  // confuse an unfamiliar proper name with lack of evidence about its language.
  const distinctive = new Set<string>();
  for (const letter of new Set(letters)) {
    const owners = compatible.filter(([, profile]) => profile.characters.has(letter));
    if (owners.length === 1) {
      distinctive.add(owners[0][0]);
    }
  }
  if (distinctive.size === 1) {
    return [{ locale: [...distinctive][0], reason: 'script', score: 1 }];
  }
  const completeVocabulary = compatible.filter(([, profile]) =>
    tokens.every((token) => profile.words.has(token)),
  );
  if (completeVocabulary.length) {
    return completeVocabulary.map(([locale]) => ({ locale, reason: 'vocabulary', score: 1 }));
  }
  const queryGrams: string[] = [];
  for (const token of tokens) {
    const padded = [...`^${token}$`];
    for (let i = 0; i < padded.length - 2; i++) {
      queryGrams.push(padded.slice(i, i + 3).join(''));
    }
  }
  const scores = compatible
    .map(([locale, profile]) => {
      let hits = 0;
      const gramScore =
        queryGrams.reduce((sum, gram) => {
          const rank = profile.grams.get(gram);
          if (rank) {
            hits++;
            return sum + Math.log1p(3000 / rank);
          }
          return sum;
        }, 0) / Math.max(1, queryGrams.length);
      const known =
        tokens.filter((token) => profile.words.has(token)).length / Math.max(1, tokens.length);
      return {
        locale,
        reason: 'corpus' as const,
        score: known * 3 + gramScore,
        known,
        coverage: hits / Math.max(1, queryGrams.length),
      };
    })
    .filter(
      (candidate) => candidate.known >= 0.5 || (letters.length > 4 && candidate.coverage >= 0.6),
    )
    .sort((a, b) => b.score - a.score);
  const best = scores[0];
  if (!best) {
    return [];
  }
  return scores
    .filter((candidate) => candidate.score >= best.score * 0.8)
    .map(({ locale, reason, score }) => ({ locale, reason, score }));
}
