import { getBibleEdition, isAvailableEdition } from './data/bibleEditions';
import { initialReadingPassage } from './public-site/readingEntry';
import { ReaderLanguageContext } from './hooks/useTranslation';
import { devWarn } from './utils/developmentDiagnostics';
import { HighlightProvider } from './contexts/HighlightContext';
import { modalComponents } from './utils/modalSurface';
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ReaderRequest, ApplyReaderIntent } from './utils/readerIntent';
import { cancelReaderRequest } from './utils/misc';
import { updateLocaleFromTranslation } from './i18n/config';
import { Routes, Route } from 'react-router-dom';
import Cookies from 'js-cookie';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import './App.css';
import './css/verse-ui.css';
import Header from './components/Header/Header';
import Dashboard from './components/Dashboard/Dashboard';
import Profile from './pages/Profile';
import Account from './pages/Account';
import { Blog } from './pages/Blog';
import LoginPage from './pages/LoginPage';
import SubscribePage from './pages/SubscribePage';
import PaymentSuccessPage from './pages/PaymentSuccessPage';
import PaymentCanceledPage from './pages/PaymentCanceledPage';
import { Box } from '@mui/material';
import CookieConsent from './components/CookieConsent/CookieConsent';
import { SubscriptionProvider } from './contexts/SubscriptionContext';
import { NotificationProvider } from './contexts/NotificationContext';
import { TourProvider } from './components/Tour';
import ScrollTriggeredSignup from './components/LeadMagnet/ScrollTriggeredSignup';
import TranslationWatcher from './components/TranslationWatcher';
import { ReaderRouteSEO } from './components/SEO/SEO';

// Import Firebase authentication
import { getAuth, onAuthStateChanged, User } from 'firebase/auth';
import Footer from './components/Footer/Footer';
// Import LoadingWrapper directly to avoid any module resolution issues
import LoadingWrapper from './components/LoadingSpinner/LoadingWrapper';
import { syncWordPressCredentials, resetWordPressCredentialsForUser } from './services/authApi';

interface Verse {
  book: string;
  chapter: number;
  verse: string | number;
  text: string;
  id: string;
}

export default function App() {
  const [authInitialized, setAuthInitialized] = useState<boolean>(false);
  const [loggedIn, setLoggedIn] = useState<boolean>(false);
  const [darkMode, setDarkMode] = useState(() => {
    try {
      return localStorage.getItem('darkMode') === 'true';
    } catch {
      return false;
    }
  });
  const [user, setUser] = useState<User | null>(null);
  const [wpToken, setWpToken] = useState<string | null>(Cookies.get('wpToken') || null); // Try to load WP token from localStorage
  const [translation, setTranslation] = useState<string>(() => {
    const resume = initialReadingPassage(window.location.hash, Cookies.get('bookmark'));
    let saved = Cookies.get('translation');
    try {
      saved ||= localStorage.getItem('translation') || undefined;
    } catch {
      // Storage is optional.
    }
    return resume.edition || saved || 'kjv';
  });
  const [data, setData] = useState<any[]>([]);
  const [verse, setVerse] = useState<Verse[]>([]);
  const [readerRequest, setReaderRequest] = useState<ReaderRequest>();
  const readerSequence = useRef(0);
  const applyReaderIntent = useCallback<ApplyReaderIntent>((intent, selectedResult) => {
    cancelReaderRequest(setData);
    setData([]);
    setVerse([]);
    Cookies.set('translation', intent.edition);
    try {
      localStorage.setItem('translation', intent.edition);
    } catch {
      // Keep the current request usable when persistent storage is unavailable.
    }
    setTranslation(intent.edition);
    updateLocaleFromTranslation();
    setReaderRequest({ sequence: ++readerSequence.current, intent, selectedResult });
    window.dispatchEvent(new CustomEvent('translationChanged', { detail: intent.edition }));
  }, []);

  // Initialize Firebase Auth
  const auth = getAuth();

  // Check for the user's theme preference on initial load
  useEffect(() => {
    // First check if there's a saved preference in localStorage
    const savedTheme = localStorage.getItem('darkMode');

    if (savedTheme !== null) {
      // Use saved preference if available
      setDarkMode(savedTheme === 'true');
    } else {
      // If no saved preference, use light mode by default instead of system preference
      setDarkMode(false);

      // Save the default preference
      localStorage.setItem('darkMode', 'false');
    }

    // Listen for changes in system theme preference (optional)
    const themeChangeListener = (e: MediaQueryListEvent) => {
      // Only change theme based on system if no explicit user preference is saved
      if (localStorage.getItem('darkMode') === null) {
        setDarkMode(e.matches);
      }
    };

    window
      .matchMedia('(prefers-color-scheme: dark)')
      .addEventListener('change', themeChangeListener);

    return () => {
      // Clean up the event listener when the component unmounts
      window
        .matchMedia('(prefers-color-scheme: dark)')
        .removeEventListener('change', themeChangeListener);
    };
  }, []);

  // Persist the actual context, keeping an unavailable saved choice explicit.
  useEffect(() => {
    if (!isAvailableEdition(translation)) {
      window.dispatchEvent(
        new CustomEvent('bibleLoadError', {
          detail:
            'The saved Bible edition is not currently available. Please select an available Bible.',
        }),
      );
      return;
    }
    Cookies.set('translation', translation);
    try {
      localStorage.setItem('translation', translation);
    } catch {
      /* Optional storage. */
    }
  }, [translation]);

  // Update HTML lang attribute based on translation
  useEffect(() => {
    const lang = getBibleEdition(translation).locale;

    if (typeof document !== 'undefined') {
      document.documentElement.lang = lang;
    }
  }, [translation]);

  // Set up the auth state listener to update the loggedIn state
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      resetWordPressCredentialsForUser(user);
      setWpToken(null);
      setAuthInitialized(true);
      if (user) {
        setLoggedIn(true);
        setUser(user);
        try {
          const credentials = await syncWordPressCredentials(user);
          if (auth.currentUser?.uid === user.uid && credentials.appPassword) {
            setWpToken(credentials.appPassword);
          }
        } catch (syncError) {
          devWarn('WordPress credential sync failed.');
        }
      } else {
        setLoggedIn(false);
        setUser(null);
        setWpToken(null);
      }
    });

    return () => unsubscribe();
  }, [auth]);

  // Define light and dark themes using MUI's createTheme
  const lightTheme = createTheme({
    components: modalComponents,
    palette: {
      mode: 'light',
      primary: {
        main: '#A1A1A1', // Customize your primary color
      },
      common: {
        white: '#ffffff',
        black: '#212121',
      },
      secondary: {
        main: '#A1A1A1', // Customize your secondary color
      },
      warning: {
        main: '#FF0000',
      },
      background: {
        default: '#ffffff', // Light mode background
        paper: '#FFFFFF', // Light paper background
      },
    },
    typography: {
      fontFamily:
        '"Helvetica Neue", "Helvetica", -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif',
    },
  });

  const darkTheme = createTheme({
    components: modalComponents,
    palette: {
      mode: 'dark',
      primary: {
        main: '#FFFFFF', // Customize your primary color for dark mode
      },
      common: {
        white: '#ffffff',
        black: '#212121',
      },
      secondary: {
        main: '#A1A1A1', // Customize your secondary color
      },
      warning: {
        main: '#FF0000',
      },
      background: {
        default: '#121212', // Dark mode background
        paper: '#1d1d1d', // Dark paper background
      },
    },
    typography: {
      fontFamily:
        '"Helvetica Neue", "Helvetica", -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif',
    },
  });

  // Choose theme based on darkMode state
  const theme = darkMode ? darkTheme : lightTheme;

  return (
    <ReaderLanguageContext.Provider value={translation}>
      <ThemeProvider theme={theme}>
        <Box
          data-theme={darkMode ? 'dark' : 'light'}
          sx={{
            backgroundColor: (theme) => (theme.palette.mode === 'light' ? 'white' : '#212121'),
            minHeight: '125vh',
          }}
        >
          <div className="App">
            <ReaderRouteSEO />
            <TranslationWatcher />
            <SubscriptionProvider>
              <NotificationProvider>
                <HighlightProvider uid={user?.uid || null} wpToken={wpToken}>
                  <Header
                    isDarkMode={darkMode}
                    loggedIn={loggedIn}
                    toggleDarkMode={() => {
                      const newMode = !darkMode;
                      setDarkMode(newMode);
                      localStorage.setItem('darkMode', newMode.toString());
                    }}
                    translation={translation}
                    setTranslation={setTranslation}
                    setData={setData}
                    verse={verse}
                    setVerse={setVerse}
                    readerRequest={readerRequest}
                    applyReaderIntent={applyReaderIntent}
                  />
                  <LoadingWrapper>
                    <Routes>
                      <Route
                        index
                        path="/"
                        element={
                          <Dashboard
                            verse={verse}
                            setVerse={setVerse}
                            data={data}
                            setData={setData}
                            translation={translation}
                            setTranslation={setTranslation}
                            readerRequest={readerRequest}
                            applyReaderIntent={applyReaderIntent}
                            user={user}
                            loggedIn={loggedIn}
                            wpToken={wpToken}
                            setWpToken={setWpToken}
                          />
                        }
                      />
                      <Route path="/blog" element={<Blog />} />
                      <Route
                        path="/profile"
                        element={
                          <Profile
                            user={user}
                            wpToken={wpToken}
                            loggedIn={loggedIn}
                            translation={translation}
                          />
                        }
                      />
                      <Route
                        path="/account"
                        element={<Account user={user} setUser={setUser} loggedIn={loggedIn} />}
                      />
                      <Route path="/login" element={<LoginPage user={user} />} />
                      <Route
                        path="/subscribe"
                        element={<SubscribePage user={user} loggedIn={loggedIn} />}
                      />
                      <Route path="/payment-success" element={<PaymentSuccessPage />} />
                      <Route path="/payment-canceled" element={<PaymentCanceledPage />} />
                    </Routes>
                    <ScrollTriggeredSignup
                      threshold={0.4}
                      rootMargin="0px"
                      authReady={authInitialized}
                      loggedIn={loggedIn}
                    />
                  </LoadingWrapper>
                  <TourProvider loggedIn={loggedIn} user={user} wpToken={wpToken} />
                  <CookieConsent />
                </HighlightProvider>
              </NotificationProvider>
            </SubscriptionProvider>
          </div>
        </Box>
        <Footer />
      </ThemeProvider>
    </ReaderLanguageContext.Provider>
  );
}
