import data from '../../data/hebrewResourceMap.generated.json';
import { CanonicalPassage } from './index';
import { VerseReference } from './contentSpans';

export type StudyResource = 'hebrew-wlc';
export type StudyResourceResolution =
  | {
      status: 'resolved';
      resource: StudyResource;
      passage: CanonicalPassage;
      references: VerseReference[];
    }
  | {
      status: 'unavailable';
      resource: StudyResource;
      passage: CanonicalPassage;
      reason: 'outside-resource' | 'absent-content' | 'unindexed-content';
      missing: VerseReference[];
    };

export const resourceReferenceKey = (ref: VerseReference): string =>
  `${ref.book.trim().toLowerCase().replace(/\s+/g, '')} ${ref.chapter}:${ref.verse}`;

const parseKey = (key: string): VerseReference => {
  const [book, label] = key.split(' ');
  const [chapter, verse] = label.split(':').map(Number);
  return { book, chapter, verse };
};

const exceptions: Record<string, { references: string[] }> = data.exceptions;
const unavailable: Record<string, { reason: string }> = data.unavailable;

/** Resolve every canonical member, never just the first post's numeric label. */
export const resolveStudyResources = (
  passage: CanonicalPassage,
  resource: StudyResource,
): StudyResourceResolution => {
  const references: VerseReference[] = [];
  for (const member of passage.kjvSpan) {
    const key = resourceReferenceKey(member);
    if (!data.books.includes(key.split(' ')[0])) {
      return {
        status: 'unavailable',
        resource,
        passage,
        reason: 'outside-resource',
        missing: [member],
      };
    }
    if (unavailable[key]) {
      return {
        status: 'unavailable',
        resource,
        passage,
        reason:
          unavailable[key].reason === 'absent-in-wlc' ? 'absent-content' : 'unindexed-content',
        missing: [member],
      };
    }
    for (const target of exceptions[key]?.references || [key]) {
      if (!references.some((ref) => resourceReferenceKey(ref) === target)) {
        references.push(parseKey(target));
      }
    }
  }
  return { status: 'resolved', resource, passage, references };
};
