import i18n, { changeLanguage } from 'i18next';
import { initReactI18next } from 'react-i18next';
import Cookies from 'js-cookie';
import { readerCatalogs } from './catalogs';
import { getBibleEdition } from '../data/bibleEditions';

function savedLocale() {
  let saved = Cookies.get('translation');
  try {
    saved ||= localStorage.getItem('translation') || undefined;
  } catch {
    // Storage is optional.
  }
  return getBibleEdition(saved).locale;
}

// i18next exports both the default instance and a named use alias.
// eslint-disable-next-line import/no-named-as-default-member
i18n.use(initReactI18next).init({
  showSupportNotice: false,
  resources: Object.fromEntries(
    Object.entries(readerCatalogs).map(([locale, translation]) => [locale, { translation }]),
  ),
  lng: savedLocale(),
  fallbackLng: 'en',
  interpolation: { escapeValue: false },
  react: { useSuspense: false },
  debug: process.env.NODE_ENV === 'development',
});

export const updateLocaleFromTranslation = () => {
  const locale = savedLocale();
  if (i18n.language !== locale) {
    changeLanguage(locale);
  }
};
export default i18n;
