import { devError } from '../../utils/developmentDiagnostics';
import { getModalSurface } from '../../utils/modalSurface';
import { useEffect, useState, useCallback, useRef } from 'react';
import Cookies from 'js-cookie';
import emojiRegex from 'emoji-regex';
import {
  TextField,
  Button,
  Typography,
  MenuItem,
  Box,
  IconButton,
  CircularProgress,
  Collapse,
} from '@mui/material';
import Menu from '@mui/material/Menu';
import Drawer from '@mui/material/Drawer';
import useMediaQuery from '@mui/material/useMediaQuery';
import { useTheme } from '@mui/material/styles';
import CloseIcon from '@mui/icons-material/Close';
import { AddComment, RefreshRounded } from '@mui/icons-material';
import ChatIcon from '@mui/icons-material/Chat';
import CommentIcon from '@mui/icons-material/Comment';
import Comment from './components/Comment'; // Import the new Comment component
import Tooltip from '@mui/material/Tooltip';

import { useTranslation } from '../../hooks/useTranslation';

import { availableKjvVerseSlug as generateKjvVerseSlug } from '../../utils/verseMappings';

import { User } from 'firebase/auth';

const WP_API_URL = process.env.REACT_APP_WP_API_URL;
const PERSPECTIVE_API_URL = process.env.REACT_APP_PERSPECTIVE_API_URL;
const PERSPECTIVE_API_KEY = process.env.REACT_APP_PERSPECTIVE_API_KEY;

const organizeComments = (allComments: any[]) => {
  const parentComments: any[] = [];
  const repliesMap: Record<number, any[]> = {};

  // Separate parent comments and replies
  allComments.forEach((comment) => {
    // Check parent field - WordPress can use parent: 0, parent: null, or parent: <id>
    // Also handle string vs number comparison
    const parentId =
      comment.parent !== undefined
        ? Number(comment.parent)
        : comment.parent_id !== undefined
          ? Number(comment.parent_id)
          : 0;

    if (parentId === 0 || isNaN(parentId)) {
      // This is a parent comment
      parentComments.push(comment);
      repliesMap[comment.id] = [];
    } else {
      // This is a reply

      if (!repliesMap[parentId]) {
        repliesMap[parentId] = [];
      }
      repliesMap[parentId].push(comment);
    }
  });

  // Attach replies to their parent comments
  parentComments.forEach((comment) => {
    comment.replies = repliesMap[comment.id] || [];
  });

  return parentComments;
};

interface FloatingCommentFormProps {
  user: User | null;
  setOpen: React.Dispatch<React.SetStateAction<boolean>>;
  position: { x: number; y: number };
  loggedIn: boolean;
  slug: string;
  setSlug: React.Dispatch<React.SetStateAction<string>>;
  comments: any[];
  setComments: React.Dispatch<React.SetStateAction<any[]>>;
  commentsMenu: { mouseX: number; mouseY: number } | null;
  open: boolean;
  setCommentsMenu: React.Dispatch<React.SetStateAction<{ mouseX: number; mouseY: number } | null>>;
  selectedVerse: any[];
  setSelectedVerse: React.Dispatch<React.SetStateAction<any[]>>;
  handleClose: () => void;
  onCommentCountUpdate?: (slug: string, count: number) => void;
  translation?: string; // Current translation (kjv, cuv, etc.)
}

const FloatingCommentForm: React.FC<FloatingCommentFormProps> = ({
  user,
  open,
  setOpen,
  position,
  loggedIn,
  slug,
  setSlug,
  comments,
  setComments,
  commentsMenu,
  setCommentsMenu,
  selectedVerse,
  setSelectedVerse,
  handleClose,
  onCommentCountUpdate,
  translation = 'kjv', // Default to KJV
}) => {
  const { t } = useTranslation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [newComment, setNewComment] = useState('');

  const [loading, setLoading] = useState(false);
  const [menuPosition, setMenuPosition] = useState(position); // Store last position
  const [dragging, setDragging] = useState(false);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [postID, setPostID] = useState<number | null>(null);
  const [charCount, setCharCount] = useState(0);
  const [page, setPage] = useState(1); // Track the current page of comments
  const [loadingMore, setLoadingMore] = useState(false); // Track if more comments are being loaded
  const [hasMoreComments, setHasMoreComments] = useState(true); // Track if there are more comments to fetch
  const [formExpanded, setFormExpanded] = useState(false); // Track if comment form is expanded
  const charLimit = 350;
  const [error, setError] = useState<string | null>(null);
  const [, setToxicityScores] = useState<Record<string, number> | null>(null);
  const [replyContext, setReplyContext] = useState<{ parentId: number; username: string } | null>(
    null,
  );

  // Handler for when user clicks reply button - expands form and pre-populates
  const handleReplyClick = (parentId: number, username: string) => {
    setReplyContext({ parentId, username });
    setFormExpanded(true);
    setNewComment(`@${username} `);
    setCharCount(`@${username} `.length);
  };

  // Clear reply context when form is collapsed or comment is cleared
  useEffect(() => {
    if (!formExpanded || newComment === '') {
      if (replyContext && newComment === '') {
        // Only clear if user cleared the form manually
        setReplyContext(null);
      }
    }
  }, [formExpanded, newComment, replyContext]);

  const checkPerspectiveAPI = async (
    comment: string,
  ): Promise<{ isValid: boolean; message?: string }> => {
    setError(null);
    setToxicityScores(null);

    if (!PERSPECTIVE_API_KEY || !PERSPECTIVE_API_URL) {
      setError('Comment moderation is currently unavailable. Please try again later.');
      return { isValid: false, message: 'Moderation service unavailable' };
    }

    try {
      const body = {
        comment: { text: comment },
        languages: ['en'],
        requestedAttributes: {
          TOXICITY: {},
          SEVERE_TOXICITY: {},
          INSULT: {},
          PROFANITY: {},
          THREAT: {},
          IDENTITY_ATTACK: {},
        },
      };

      const response = await fetch(`${PERSPECTIVE_API_URL}?key=${PERSPECTIVE_API_KEY}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      // Store all toxicity scores
      const scores = {
        toxicity: data.attributeScores.TOXICITY.summaryScore.value,
        severeToxicity: data.attributeScores.SEVERE_TOXICITY.summaryScore.value,
        insult: data.attributeScores.INSULT.summaryScore.value,
        profanity: data.attributeScores.PROFANITY.summaryScore.value,
        threat: data.attributeScores.THREAT?.summaryScore.value || 0,
        identityAttack: data.attributeScores.IDENTITY_ATTACK?.summaryScore.value || 0,
      };
      setToxicityScores(scores);

      // Check for various types of inappropriate content
      const violations = [];
      if (scores.toxicity > 0.7) {
        violations.push('toxic language');
      }
      if (scores.severeToxicity > 0.7) {
        violations.push('severely toxic content');
      }
      if (scores.insult > 0.7) {
        violations.push('insulting content');
      }
      if (scores.profanity > 0.7) {
        violations.push('profanity');
      }
      if (scores.threat > 0.7) {
        violations.push('threatening content');
      }
      if (scores.identityAttack > 0.7) {
        violations.push('discriminatory content');
      }

      if (violations.length > 0) {
        const message = `Your comment contains ${violations.join(
          ', ',
        )}. Please revise and try again.`;
        setError(message);
        return { isValid: false, message };
      }

      return { isValid: true };
    } catch (error) {
      devError('Error checking content.');
      setError('Unable to verify comment content. Please try again.');
      return { isValid: false, message: 'Error checking content' };
    }
  };

  async function removeEmojis(text: string) {
    return text.replace(emojiRegex(), '');
  }

  // Function to decode HTML entities in error messages

  const handleCommentSubmit = async () => {
    if (!newComment.trim()) {
      return;
    }

    const wpToken = Cookies.get('wpToken');
    if (!wpToken) {
      setError(String(t('comments.pleaseLogInToPost')));
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const cleanComment = await removeEmojis(newComment);
      const { isValid } = await checkPerspectiveAPI(cleanComment);

      if (!isValid) {
        setLoading(false);
        return;
      }

      const response = await fetch(`${WP_API_URL}/comments`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Basic ${btoa(`${user?.email || ''}:${wpToken}`)}`,
        },
        body: JSON.stringify({
          content: cleanComment,
          post: postID,
          post_slug: slug,
          parent: replyContext?.parentId || undefined, // Include parent ID if replying
          meta: {
            translation: translation, // Include translation meta for filtering
          },
        }),
      });

      if (!response.ok) {
        // Try to get the error message from the response
        setLoading(false);
        let errorMessage = `HTTP error! status: ${response.status}`;
        try {
          const errorData = await response.json();
          if (errorData && errorData.message) {
            errorMessage = errorData.message;
          }
          setLoading(false);
        } catch (jsonError) {
          // If response can't be parsed as JSON, use the status text
          errorMessage = response.statusText || errorMessage;
        }
        throw new Error(errorMessage);
      }

      setNewComment('');
      setCharCount(0);
      setError(null);
      setReplyContext(null); // Clear reply context after successful submission
      setFormExpanded(false); // Collapse form after successful submission
      if (postID !== null) {
        fetchComments(postID);
      }
      // We don't want to reset the comments menu position after posting
      // Removing: setCommentsMenu(null);
    } catch (error: unknown) {
      devError('Error submitting comment.');
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      setError(`${String(t('comments.failedToPostComment'))} ${errorMessage}`);
    } finally {
      setLoading(false);
    }
  };

  // Function to organize comments into parent comments with their replies
  const commentCountCallback = useRef(onCommentCountUpdate);
  commentCountCallback.current = onCommentCountUpdate;
  const currentSlug = useRef(slug);
  currentSlug.current = slug;
  const commentRequest = useRef(0);
  const loadedPost = useRef<number | null>(null);

  const fetchComments = useCallback(
    async (postId: number, page = 1, requestSlug = currentSlug.current) => {
      const request = ++commentRequest.current;
      if (!postId || !WP_API_URL) {
        return;
      }
      setLoading(true);
      try {
        // Fetch ALL comments (including replies) for this post
        // WordPress REST API should return all comments regardless of parent
        // Include status=approved to get approved comments, and also try without status filter
        const wpToken = Cookies.get('wpToken');
        const headers: HeadersInit = {
          'Content-Type': 'application/json',
        };

        // Add authentication if available (might be needed to see all comments)
        if (wpToken && user) {
          headers['Authorization'] = `Basic ${btoa(`${user?.email || ''}:${wpToken}`)}`;
        }

        const response = await fetch(
          `${WP_API_URL}/comments?post=${postId}&page=${page}&per_page=100&orderby=date&order=asc`,
          { headers },
        );
        const data = await response.json();
        if (request !== commentRequest.current) {
          return;
        }

        // Also try fetching replies using the children link if available
        const commentsWithReplies = await Promise.all(
          data.map(async (comment: any) => {
            // If comment has children link, try to fetch them
            if (comment._links?.children && comment._links.children.length > 0) {
              const childrenUrl = comment._links.children[0].href;
              try {
                const childrenResponse = await fetch(childrenUrl, { headers });
                if (childrenResponse.ok) {
                  const children = await childrenResponse.json();

                  if (children.length > 0) {
                    return {
                      ...comment,
                      replies: children,
                    };
                  }
                }
              } catch (error) {
                devError('Error fetching comment replies.');
              }
            }
            // If no children found via API, check if there are replies in the main data
            return comment;
          }),
        );

        if (request !== commentRequest.current) {
          return;
        }
        // After trying children links, organize everything
        const allCommentsWithReplies = [...data];
        commentsWithReplies.forEach((commentWithReplies: any) => {
          if (commentWithReplies.replies && commentWithReplies.replies.length > 0) {
            // Find the comment in allComments and add replies
            const index = allCommentsWithReplies.findIndex(
              (c: any) => c.id === commentWithReplies.id,
            );
            if (index >= 0) {
              allCommentsWithReplies[index] = commentWithReplies;
            } else {
              allCommentsWithReplies.push(commentWithReplies);
            }
          }
        });

        // Filter comments by translation before organizing
        const filteredData = allCommentsWithReplies.filter((comment: any) => {
          const commentTranslation = comment.translation || comment.meta?.translation || 'kjv'; // Default to 'kjv'
          return commentTranslation === translation;
        });

        // Now organize all comments (including those fetched via children links)
        const allComments = organizeComments(filteredData);

        // Merge replies from children links into organized structure
        commentsWithReplies.forEach((commentWithReplies: any) => {
          const commentTranslation =
            commentWithReplies.translation || commentWithReplies.meta?.translation || 'kjv';
          // Only merge replies if the parent comment matches the current translation
          if (
            commentTranslation === translation &&
            commentWithReplies.replies &&
            commentWithReplies.replies.length > 0
          ) {
            const organizedComment = allComments.find((c: any) => c.id === commentWithReplies.id);
            if (organizedComment) {
              // Filter replies by translation as well
              const filteredReplies = commentWithReplies.replies.filter((reply: any) => {
                const replyTranslation = reply.translation || reply.meta?.translation || 'kjv';
                return replyTranslation === translation;
              });
              // Merge replies, avoiding duplicates
              const existingReplyIds = new Set(organizedComment.replies.map((r: any) => r.id));
              const newReplies = filteredReplies.filter((r: any) => !existingReplyIds.has(r.id));
              organizedComment.replies = [...organizedComment.replies, ...newReplies];
            }
          }
        });

        const organizedComments = allComments;

        // Always clear loading state, regardless of whether we have comments
        setLoading(false);

        if (data.length === 0 || organizedComments.length === 0) {
          // No comments in API response OR all comments filtered out by translation
          setHasMoreComments(false);
          if (page === 1) {
            setComments([]);
          }
        } else {
          if (page === 1) {
            setComments(organizedComments);
          } else {
            // Merge new comments with existing ones
            setComments((prevComments) => {
              const existingIds = new Set(prevComments.map((c) => c.id));
              const newParents = organizedComments.filter((c) => !existingIds.has(c.id));
              return [...prevComments, ...newParents];
            });
          }

          // Update hasMoreComments based on whether we got a full page of comments
          setHasMoreComments(data.length >= 100);
        }

        // Update comment count for this verse/thread (including replies)
        if (commentCountCallback.current) {
          const totalCount = organizedComments.reduce(
            (acc: number, comment: any) =>
              acc + 1 + (Array.isArray(comment.replies) ? comment.replies.length : 0),
            0,
          );
          commentCountCallback.current(requestSlug, totalCount);
        }
      } catch (error) {
        devError('Error fetching comments.');
      } finally {
        if (request === commentRequest.current) {
          setLoading(false);
          setLoadingMore(false);
        }
      }
    },
    [user, translation, setComments],
  );

  const handleReplySubmitted = () => {
    // Refresh comments after reply is submitted
    if (postID) {
      fetchComments(postID, 1);
    }
  };

  useEffect(() => {
    let cancelled = false;
    setPage(1);
    setPostID(null);
    loadedPost.current = null;
    setLoadingMore(false);
    if (commentsMenu && selectedVerse[0]) {
      const selected = selectedVerse[0];
      const newSlug = generateKjvVerseSlug(
        selected.book.trim() || '',
        selected.chapter || 1,
        selected.verse ?? 1,
        translation,
      );
      if (!newSlug) {
        setSlug('');
        setComments([]);
        setLoading(false);
        return;
      }
      setSlug(newSlug);
      setLoading(true);
      void fetch(`${WP_API_URL}/posts?slug=${newSlug}`)
        .then((response) => response.json())
        .then((data) => {
          if (cancelled) {
            return;
          }
          const postId = data[0]?.id;
          if (postId) {
            loadedPost.current = postId;
            setPostID(postId);
            return fetchComments(postId, 1, newSlug);
          }
          setComments([]);
          setLoading(false);
        })
        .catch(() => {
          if (!cancelled) {
            devError('Error fetching post ID.');
            setLoading(false);
          }
        });
    } else {
      setComments([]);
      setLoading(false);
    }
    return () => {
      cancelled = true;
      commentRequest.current += 1;
    };
  }, [commentsMenu, selectedVerse, translation, setSlug, setComments, fetchComments]);

  const handleViewComments = async () => {
    if (postID) {
      await fetchComments(postID);
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setDragging(true);
    setOffset({ x: e.clientX - menuPosition.x, y: e.clientY - menuPosition.y });
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!dragging) {
        return;
      }
      setMenuPosition({ x: e.clientX - offset.x, y: e.clientY - offset.y });
    };

    const handleMouseUp = () => {
      setDragging(false);
    };

    if (dragging) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
    }

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [dragging, offset]);

  const handleCommentChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (value.length <= charLimit) {
      setNewComment(value);
      setCharCount(value.length);
    }
  };

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    // Don't fetch more if we know there are no more comments
    if (!hasMoreComments || loadingMore) {
      return;
    }

    const { scrollTop, scrollHeight, clientHeight } = e.currentTarget;
    if (scrollTop + clientHeight >= scrollHeight - 5) {
      setLoadingMore(true);
      setPage((prevPage) => prevPage + 1);
    }
  };

  useEffect(() => {
    if (page > 1 && postID && loadedPost.current === postID) {
      fetchComments(postID, page);
    }
  }, [page, postID, fetchComments]);

  if (!open) {
    return null;
  }
  const isDarkMode = theme.palette.mode === 'dark';

  // Shared content for mobile and desktop
  const renderContent = () => (
    <Box
      sx={{
        width: '100%',
        display: 'flex',
        flexDirection: 'column',
        overflowY: 'hidden',
        flex: { xs: 'none', sm: formExpanded ? 1 : 'none' },
        minHeight: 0,
        maxHeight: { xs: '70vh', sm: formExpanded ? 'calc(100vh - 150px)' : 'none' },
      }}
    >
      <Tooltip
        title={String(t('comments.refreshComments'))}
        sx={{
          opacity: 0.75,
          my: 2,
          '&.MuiIconButton-root:hover': {
            backgroundColor: 'rgba(0, 0, 0, 0.00)',
            opacity: 1,
          },
        }}
      >
        <IconButton disableRipple onClick={handleViewComments} size="small" color="primary">
          <ChatIcon sx={{ mt: -1, color: isDarkMode ? '#FFF' : '#000' }} fontSize="inherit" />
          <CommentIcon sx={{ color: isDarkMode ? '#FFF' : '#000' }} fontSize="inherit" />
        </IconButton>
      </Tooltip>

      {/* Scrollable comments section with modern styling */}
      <Box
        sx={{
          height: formExpanded ? 0 : { xs: '55vh', sm: 450 },
          overflow: formExpanded ? 'hidden' : 'auto',
          overflowX: 'hidden',
          transition: 'height 0.3s ease-in-out, opacity 0.3s ease-in-out',
          opacity: formExpanded ? 0 : 1,
          padding: formExpanded ? 0 : 0,
          marginBottom: formExpanded ? 0 : 7.5,
          border: formExpanded
            ? 'none'
            : (theme) =>
                `1px solid ${theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.08)'}`,
          borderRadius: formExpanded ? 0 : 1.5,
          backgroundColor: (theme) =>
            theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.02)' : 'rgba(0, 0, 0, 0.01)',
          backdropFilter: 'blur(10px)',
          // Hide scrollbar for Chrome, Safari, and Edge
          '&::-webkit-scrollbar': {
            display: 'none',
          },
          // Hide scrollbar for Firefox
          scrollbarWidth: 'none',
          // Ensure scrolling still works
          msOverflowStyle: 'none',
        }}
        onScroll={handleScroll}
      >
        {loading ? (
          <Box
            sx={{
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              minHeight: '150px', // Fixed height to maintain container shape
              width: '100%',
            }}
          >
            <CircularProgress color={'success'} />
          </Box>
        ) : comments.length > 0 ? (
          comments.map((comment: any) => (
            <Comment
              key={comment.id}
              comment={comment}
              user={user}
              replies={comment.replies || []}
              postID={postID}
              onReplySubmitted={handleReplySubmitted}
              onReplyClick={handleReplyClick}
            />
          ))
        ) : !hasMoreComments ? (
          /* Show the empty state message when hasMoreComments is false (API returned empty array) */
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              justifyContent: 'center',
              alignItems: 'center',
              height: '150px',
            }}
          >
            <Typography
              variant="body2"
              sx={{
                textAlign: 'center',
                color: (theme) =>
                  theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.5)' : 'rgba(0, 0, 0, 0.5)',
                padding: 1.5,
                fontSize: '0.8125rem',
              }}
            >
              {String(t('comments.noComments'))}
            </Typography>
          </Box>
        ) : (
          <Box
            sx={{
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              height: '150px',
            }}
          >
            <CircularProgress color={'success'} />
          </Box>
        )}
        {loadingMore && hasMoreComments && (
          <Box
            sx={{
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              mt: 2,
              mb: 2, // Added bottom margin for consistent spacing
            }}
          >
            <CircularProgress color={'warning'} size={24} />
          </Box>
        )}
        {!hasMoreComments && comments.length > 0 && (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              justifyContent: 'center',
              alignItems: 'center',
              mt: 1.5,
              p: 1.5,
              border: (theme) =>
                `0px solid ${theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.08)'}`,
              borderRadius: 1.5,
              backgroundColor: 'transparent',
            }}
          ></Box>
        )}
      </Box>
      {/* Refresh Icon Button */}
      <Box
        sx={{
          position: 'relative',
          opacity: formExpanded ? 0 : 1,
          transition: 'opacity 0.3s ease-in-out',
          pointerEvents: formExpanded ? 'none' : 'auto',
        }}
      >
        <IconButton
          onClick={handleViewComments}
          size="small"
          color="primary"
          sx={{
            position: 'absolute',
            left: '88%',
            bottom: 40,
          }}
        >
          <RefreshRounded fontSize="small" />
        </IconButton>
        <Tooltip
          title={String(t('comments.addComment'))}
          sx={{
            opacity: 0.75,
            mb: 0,
            mt: -10,
            '&.MuiIconButton-root:hover': {
              backgroundColor: 'rgba(0, 0, 0, 0.00)',
              opacity: 1,
            },
          }}
        >
          <IconButton
            disableRipple
            onClick={() => setFormExpanded(!formExpanded)}
            size="small"
            color="primary"
          >
            <AddComment sx={{ color: isDarkMode ? '#FFF' : '#000' }} fontSize="inherit" />
            <Typography
              variant="caption"
              sx={{
                fontSize: '0.75rem',
                color: (theme) =>
                  theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.6)' : 'rgba(0, 0, 0, 0.6)',
              }}
            >
              &nbsp;{String(t('comments.comment'))}
            </Typography>
          </IconButton>
        </Tooltip>
      </Box>
      <Box
        sx={{
          width: '100%',
          display: 'flex',
          flexDirection: 'row',
          gap: 2,
          maxHeight: { xs: '70vh', sm: 'none' },
        }}
      ></Box>
      {/* Comment Form Section - Collapsible */}
      {loggedIn && (
        <Collapse
          in={formExpanded}
          timeout={300}
          sx={{ width: '100%', flex: { xs: 'none', sm: formExpanded ? 1 : 'none' }, minHeight: 0 }}
        >
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              gap: 0,
              mt: -5.5,
              flex: { xs: 'none', sm: formExpanded ? 1 : 'none' },
              minHeight: 0,
              overflowY: 'auto',
              // Hide scrollbar
              '&::-webkit-scrollbar': {
                display: 'none',
              },
              scrollbarWidth: 'none',
              msOverflowStyle: 'none',
            }}
          >
            {/* Moderation Notice */}
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                mt: 1,
                mb: 0.5,
                py: 1,
                borderRadius: 1,
                backgroundColor: (theme) =>
                  theme.palette.mode === 'dark'
                    ? 'rgba(255, 255, 255, 0.03)'
                    : 'rgba(0, 0, 0, 0.02)',
                border: (theme) =>
                  `1px solid ${theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.06)' : 'rgba(0, 0, 0, 0.06)'}`,
              }}
            >
              <Typography
                variant="caption"
                sx={{
                  fontSize: '0.5rem',
                  color: (theme) =>
                    theme.palette.mode === 'dark'
                      ? 'rgba(255, 255, 255, 0.6)'
                      : 'rgba(0, 0, 0, 0.6)',
                  textAlign: 'center',
                  fontStyle: 'italic',
                  lineHeight: 1.2,
                  textWrap: 'wrap',
                  mx: 1,
                }}
              >
                {String(t('comments.moderationNotice'))}
              </Typography>
            </Box>

            {/* Comment Input Section with modern styling */}
            <Box
              sx={{
                display: 'flex',
                flexDirection: 'column',
                gap: 1,
                mt: { xs: 0.5, sm: 1 },
                p: 1.5,
                borderRadius: 1.5,
                backgroundColor: (theme) =>
                  theme.palette.mode === 'dark'
                    ? 'rgba(255, 255, 255, 0.02)'
                    : 'rgba(0, 0, 0, 0.01)',
              }}
            >
              <TextField
                label={
                  replyContext
                    ? String(t('comments.replyTo', { name: replyContext.username })).replace(
                        '...',
                        '',
                      )
                    : String(t('comments.addCommentLabel'))
                }
                value={newComment}
                onChange={handleCommentChange}
                fullWidth
                multiline
                rows={8}
                placeholder={
                  replyContext
                    ? String(t('comments.replyTo', { name: replyContext.username }))
                    : String(t('comments.addCommentPlaceholder'))
                }
                size="small"

                sx={{
                  '& .MuiOutlinedInput-root': {
                    backgroundColor: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(255, 255, 255, 0.03)'
                        : 'rgba(0, 0, 0, 0.02)',
                    borderRadius: 1.5,
                    transition: 'all 0.2s ease-in-out',
                    '& fieldset': {
                      borderColor: (theme) =>
                        theme.palette.mode === 'dark'
                          ? 'rgba(255, 255, 255, 0.12)'
                          : 'rgba(0, 0, 0, 0.12)',
                      transition: 'border-color 0.2s ease-in-out',
                    },
                    '&:hover fieldset': {
                      borderColor: (theme) =>
                        theme.palette.mode === 'dark'
                          ? 'rgba(255, 255, 255, 0.2)'
                          : 'rgba(0, 0, 0, 0.2)',
                    },
                    '&.Mui-focused': {
                      backgroundColor: (theme) =>
                        theme.palette.mode === 'dark'
                          ? 'rgba(255, 255, 255, 0.05)'
                          : 'rgba(0, 0, 0, 0.03)',
                      '& fieldset': {
                        borderColor: (theme) =>
                          theme.palette.mode === 'dark'
                            ? 'rgba(255, 255, 255, 0.3)'
                            : 'rgba(0, 0, 0, 0.3)',
                        borderWidth: '1.5px',
                      },
                    },
                  },
                  '& .MuiInputLabel-root': {
                    color: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(255, 255, 255, 0.6)'
                        : 'rgba(0, 0, 0, 0.6)',
                    '&.Mui-focused': {
                      color: (theme) =>
                        theme.palette.mode === 'dark'
                          ? 'rgba(255, 255, 255, 0.8)'
                          : 'rgba(0, 0, 0, 0.8)',
                    },
                  },
                  '& .MuiInputBase-input': {
                    fontSize: '0.75rem',
                    color: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(255, 255, 255, 0.9)'
                        : 'rgba(0, 0, 0, 0.9)',
                    '&::placeholder': {
                      color: (theme) =>
                        theme.palette.mode === 'dark'
                          ? 'rgba(255, 255, 255, 0.4)'
                          : 'rgba(0, 0, 0, 0.4)',
                      opacity: 1,
                    },
                  },
                }}
              />
              {error && (
                <Box
                  sx={{
                    p: 1.5,
                    borderRadius: 1.5,
                    backgroundColor: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(211, 47, 47, 0.15)'
                        : 'rgba(211, 47, 47, 0.1)',
                    border: (theme) =>
                      `1px solid ${theme.palette.mode === 'dark' ? 'rgba(211, 47, 47, 0.3)' : 'rgba(211, 47, 47, 0.2)'}`,
                  }}
                >
                  <Typography
                    variant="body2"
                    sx={{
                      color: (theme) =>
                        theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.9)' : '#d32f2f',
                      wordBreak: 'break-word',
                      whiteSpace: 'normal',
                      overflowWrap: 'break-word',
                      fontSize: '0.65rem',
                    }}
                  >
                    <div dangerouslySetInnerHTML={{ __html: error }} />
                  </Typography>
                </Box>
              )}
              <Box
                sx={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                }}
              >
                <Typography
                  variant="caption"
                  sx={{
                    color: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(255, 255, 255, 0.5)'
                        : 'rgba(0, 0, 0, 0.5)',
                    fontSize: '0.5rem',
                  }}
                >
                  {String(t('comments.pressEnterToAddLine'))}
                </Typography>
                <Typography
                  variant="body2"
                  sx={{
                    color:
                      charCount >= charLimit - 10 && charCount <= charLimit
                        ? (theme) => theme.palette.error.main
                        : (theme) =>
                            theme.palette.mode === 'dark'
                              ? 'rgba(255, 255, 255, 0.5)'
                              : 'rgba(0, 0, 0, 0.5)',
                    fontSize: '0.8125rem',
                    fontWeight: charCount >= charLimit - 10 && charCount <= charLimit ? 600 : 400,
                  }}
                >
                  {charCount}/{charLimit}
                </Typography>
              </Box>
              <Button
                onClick={handleCommentSubmit}
                variant="contained"
                size="small"
                disabled={loading || charCount > charLimit || !newComment.trim()}
                sx={{
                  py: 0.875,
                  fontSize: '0.8125rem',
                  fontWeight: 500,
                  borderRadius: 1.5,
                  textTransform: 'none',
                  backgroundColor: (theme) =>
                    theme.palette.mode === 'dark'
                      ? 'rgba(255, 255, 255, 0.1)'
                      : 'rgba(0, 0, 0, 0.8)',
                  color: (theme) =>
                    theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.9)' : '#ffffff',
                  border: (theme) =>
                    `1px solid ${theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.2)' : 'transparent'}`,
                  transition: 'all 0.2s ease-in-out',
                  '&:hover:not(:disabled)': {
                    backgroundColor: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(255, 255, 255, 0.15)'
                        : 'rgba(0, 0, 0, 0.9)',
                    borderColor: (theme) =>
                      theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.3)' : 'transparent',
                    transform: 'translateY(-1px)',
                    boxShadow: (theme) =>
                      theme.palette.mode === 'dark'
                        ? '0 4px 12px rgba(255, 255, 255, 0.1)'
                        : '0 4px 12px rgba(0, 0, 0, 0.15)',
                  },
                  '&:active:not(:disabled)': {
                    transform: 'translateY(0)',
                  },
                  '&:disabled': {
                    opacity: 0.5,
                    cursor: 'not-allowed',
                  },
                }}
                type="submit"
                fullWidth
              >
                {loading ? (
                  <Box
                    sx={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: 1,
                    }}
                  >
                    <CircularProgress
                      size={16}
                      sx={{
                        color: (theme) =>
                          theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.9)' : '#ffffff',
                      }}
                    />
                    <span>{String(t('comments.posting'))}</span>
                  </Box>
                ) : (
                  String(t('comments.postComment'))
                )}
              </Button>
            </Box>
          </Box>
        </Collapse>
      )}
    </Box>
  );

  // Mobile: bottom drawer
  if (isMobile) {
    return (
      <Drawer
        anchor="bottom"
        open={open}
        onClose={() => {
          setOpen(false);
          handleClose();
          setSelectedVerse([]);
          setCommentsMenu(null);
          setComments([]);
        }}
        PaperProps={{
          sx: (theme) => ({
            ...getModalSurface(theme.palette.mode),
            borderBottomLeftRadius: 0,
            borderBottomRightRadius: 0,
            maxHeight: '80vh',
          }),
        }}
      >
        <Box
          sx={{
            position: 'relative',
          }}
        >
          <IconButton
            sx={{ position: 'absolute', right: 8, top: 8 }}
            size="small"
            onClick={() => {
              setOpen(false);
              handleClose();
              setSelectedVerse([]);
              setCommentsMenu(null);
              setComments([]);
            }}
          >
            <CloseIcon fontSize="small" />
          </IconButton>
          {renderContent()}
        </Box>
      </Drawer>
    );
  }

  // Desktop: existing draggable menu
  return (
    <Menu
      PaperProps={{ sx: (theme) => getModalSurface(theme.palette.mode) }}
      elevation={3}
      open={open}
      anchorReference="anchorPosition"
      anchorPosition={{
        top: (menuPosition && menuPosition.y) || 100,
        left: (menuPosition && menuPosition.x) || 20,
      }}
      sx={{
        '& ul': { padding: 0 },
      }}
    >
      <MenuItem
        disableRipple
        sx={{
          height: 'auto',
          minWidth: 350,
          maxWidth: '100%',
          padding: 0,
          '&:hover': { backgroundColor: 'transparent' },
        }}
      >
        <Box
          sx={{
            minWidth: { xs: '50vw', sm: 380 },
            maxWidth: { xs: '100vw', sm: 420 },
            padding: 2,
            cursor: dragging ? 'grabbing' : 'grab',
            userSelect: 'none',

            '&:hover': { backgroundColor: 'transparent' },
            display: 'flex',
            flexDirection: 'column',
            height: { xs: 'auto', sm: formExpanded ? 'calc(100vh - 150px)' : 'auto' },
            maxHeight: { xs: 'auto', sm: formExpanded ? 'calc(100vh - 150px)' : 'none' },
          }}
          onMouseDown={handleMouseDown}
        >
          <IconButton
            sx={{ position: 'absolute', right: 8, top: 8 }}
            size="small"
            onClick={() => {
              setOpen(false);
              handleClose();
              setSelectedVerse([]);
              setCommentsMenu(null);
              setComments([]);
            }}
          >
            <CloseIcon fontSize="small" />
          </IconButton>
          {renderContent()}
        </Box>
      </MenuItem>
    </Menu>
  );
};

export default FloatingCommentForm;
