import { interfaceText } from '../../i18n/interfaceText';
import React, { useState, useEffect, useId } from 'react';
import { Alert, Box, Typography, CircularProgress, Tooltip, Button } from '@mui/material';
import SubscriptionCheck from '../Subscription/SubscriptionCheck';
import { getReadingProgress, getReadingStreak } from '../../services/readingService';
import { useTranslation } from '../../hooks/useTranslation';
import { translateBookName } from '../../utils/bookTranslations';

// Types
interface ReadingDay {
  date: string;
  completed: boolean;
  chapters_read: number;
}

interface ReadingStats {
  current_streak: number;
  longest_streak: number;
  last_30_days: ReadingDay[];
  total_days_read: number;
  average_chapters_per_day: number;
}

interface ReadingProgress {
  reading_progress: {
    [book: string]: number[];
  };
}

// Helper function to generate dates for calendar
const generateCalendarDays = (days: ReadingDay[]) => {
  // Create an indexed map of completed days for easy lookup
  const completedDaysMap = days.reduce((acc: Record<string, ReadingDay>, day) => {
    acc[day.date] = day;
    return acc;
  }, {});

  // Generate a 30-day calendar (including empty days)
  const calendar: (ReadingDay | null)[] = [];
  const today = new Date();

  for (let i = 0; i < 30; i++) {
    const date = new Date();
    date.setDate(today.getDate() - i);

    const dateStr = date.toISOString().split('T')[0];

    if (completedDaysMap[dateStr]) {
      calendar.unshift(completedDaysMap[dateStr]);
    } else {
      calendar.unshift({
        date: dateStr,
        completed: false,
        chapters_read: 0,
      });
    }
  }

  return calendar;
};

const ReadingStatsPanel: React.FC<{ user: any; wpToken: string; compact?: boolean }> = ({
  user,
  wpToken,
  compact = false,
}) => {
  const { t, language } = useTranslation();
  const sectionId = useId();
  const [stats, setStats] = useState<ReadingStats | null>(null);
  const [readingProgress, setReadingProgress] = useState<ReadingProgress | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [retry, setRetry] = useState(0);
  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    setError(null);
    setStats(null);
    setReadingProgress(null);
    if (!user || !wpToken) {
      setError('Sign in to load your reading statistics.');
      setLoading(false);
      return () => controller.abort();
    }
    Promise.all([
      getReadingStreak(wpToken, user, controller.signal),
      getReadingProgress(wpToken, user, controller.signal),
    ])
      .then(([streak, progress]) => {
        if (controller.signal.aborted) {
          return;
        }
        if (!streak) {
          throw new Error('Reading statistics unavailable');
        }
        setStats(streak);
        setReadingProgress({ reading_progress: progress });
      })
      .catch(() => {
        if (!controller.signal.aborted) {
          setError(
            'Reading statistics are currently unavailable. This does not mean your progress is zero.',
          );
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      });
    return () => controller.abort();
  }, [user, wpToken, retry]);

  if (loading) {
    return (
      <Box role="status" sx={{ display: 'flex', alignItems: 'center', gap: 1.5, py: 3 }}>
        <CircularProgress size={18} color="inherit" />
        <Typography sx={{ fontSize: 13, color: 'text.secondary' }}>
          {interfaceText('Loading reading activity…')}
        </Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Alert
        severity="warning"
        sx={{ fontSize: 13 }}
        action={
          <Button size="small" onClick={() => setRetry((value) => value + 1)}>
            {interfaceText('Retry')}
          </Button>
        }
      >
        {interfaceText(error)}
      </Alert>
    );
  }

  const calendarDays = stats ? generateCalendarDays(stats.last_30_days) : [];
  const leadingDays =
    compact && calendarDays[0] ? new Date(`${calendarDays[0].date}T00:00:00`).getDay() : 0;

  const getBookStats = () => {
    if (!readingProgress?.reading_progress) {
      return null;
    }

    const totalBooks = Object.keys(readingProgress.reading_progress).length;
    const totalChapters = Object.values(readingProgress.reading_progress).reduce(
      (sum, chapters) => sum + chapters.length,
      0,
    );

    const booksWithChapters = Object.entries(readingProgress.reading_progress)
      .map(([book, chapters]) => ({
        book,
        chaptersRead: chapters.length,
        chapters: Array.isArray(chapters) ? chapters.sort((a, b) => a - b) : [],
      }))
      .sort((a, b) => b.chaptersRead - a.chaptersRead);

    return {
      totalBooks,
      totalChapters,
      booksWithChapters,
    };
  };

  const bookStats = getBookStats();

  return (
    <SubscriptionCheck feature="all">
      <Box component="section" aria-labelledby={`${sectionId}-activity`}>
        <Typography
          id={`${sectionId}-activity`}
          component="h2"
          sx={{ fontSize: 15, fontWeight: 600, mb: 3 }}
        >
          {interfaceText('Reading activity')}
        </Typography>

        {stats && (
          <>
            <Box
              component="dl"
              sx={{
                display: 'grid',
                gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
                m: 0,
                mb: 4,
              }}
            >
              {[
                { label: 'Current streak', value: stats.current_streak },
                { label: 'Longest streak', value: stats.longest_streak },
                { label: 'Days read', value: stats.total_days_read },
              ].map(({ label, value }, index) => (
                <Box
                  key={label}
                  sx={{
                    pl: index ? { xs: 1.5, sm: 3 } : 0,
                    borderLeft: index ? 1 : 0,
                    borderColor: 'divider',
                  }}
                >
                  <Typography
                    component="dt"
                    sx={{ fontSize: 12, color: 'text.secondary', mb: 0.75 }}
                  >
                    {label === 'Longest streak' ? t('games.longest') : interfaceText(label)}
                  </Typography>
                  <Typography
                    component="dd"
                    sx={{
                      m: 0,
                      fontSize: 26,
                      lineHeight: 1.2,
                      fontWeight: 500,
                      fontVariantNumeric: 'tabular-nums',
                    }}
                  >
                    {value}
                    <Box
                      component="span"
                      sx={{ ml: 0.75, fontSize: 11, fontWeight: 400, color: 'text.secondary' }}
                    >
                      {value === 1 ? interfaceText('day') : interfaceText('days')}
                    </Box>
                  </Typography>
                </Box>
              ))}
            </Box>

            <Box
              component="section"
              aria-labelledby={`${sectionId}-calendar`}
              sx={{ pb: 3, borderBottom: 1, borderColor: 'divider' }}
            >
              <Typography
                id={`${sectionId}-calendar`}
                component="h3"
                sx={{ fontSize: 13, fontWeight: 600, mb: 1.5 }}
              >
                {interfaceText('Last 30 days')}
              </Typography>
              <Box
                sx={{
                  display: 'grid',
                  gridTemplateColumns: compact
                    ? `repeat(${Math.ceil((leadingDays + calendarDays.length) / 7)}, 14px)`
                    : {
                        xs: 'repeat(15, minmax(0, 1fr))',
                        sm: 'repeat(30, minmax(0, 1fr))',
                      },
                  gridTemplateRows: compact ? 'repeat(7, 14px)' : undefined,
                  gridAutoFlow: compact ? 'column' : undefined,
                  gap: 0.5,
                }}
              >
                {Array.from({ length: leadingDays }, (_, index) => (
                  <Box key={`padding-${index}`} aria-hidden="true" />
                ))}
                {calendarDays.map((day, index) => {
                  const label = day
                    ? `${new Date(day.date).toLocaleDateString(language)}: ${day.completed ? interfaceText('{{chapters_read}} chapters read', { chapters_read: day.chapters_read }) : interfaceText('No reading activity')}`
                    : '';
                  return (
                    <Tooltip key={index} title={label} describeChild>
                      <Box
                        tabIndex={0}
                        role="img"
                        aria-label={label}
                        sx={{
                          aspectRatio: '1',
                          maxHeight: 28,
                          borderRadius: '2px',
                          border: 1,
                          bgcolor: [
                            '#202020',
                            '#484848',
                            '#777777',
                            '#aaaaaa',
                            '#dddddd',
                            '#ffffff',
                          ][day?.completed ? Math.min(Math.ceil(day.chapters_read / 2), 5) : 0],
                          borderColor: day?.completed ? 'text.primary' : 'divider',
                          '&:focus-visible': {
                            outline: '2px solid',
                            outlineColor: 'text.primary',
                            outlineOffset: 2,
                          },
                        }}
                      />
                    </Tooltip>
                  );
                })}
              </Box>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, mt: 1.25 }}>
                <Typography sx={{ fontSize: 11, color: 'text.secondary' }}>
                  {interfaceText('Past 30 days → today')}
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75 }}>
                  <Box
                    aria-hidden="true"
                    sx={{ width: 8, height: 8, borderRadius: '1px', bgcolor: '#ffffff' }}
                  />
                  <Typography sx={{ fontSize: 11, color: 'text.secondary' }}>
                    {interfaceText('Reading recorded')}
                  </Typography>
                </Box>
              </Box>
            </Box>

            {!compact && (
              <Box component="section" aria-labelledby={`${sectionId}-books`} sx={{ pt: 3 }}>
                <Box
                  sx={{
                    display: 'flex',
                    alignItems: 'baseline',
                    justifyContent: 'space-between',
                    gap: 1.5,
                    flexWrap: 'wrap',
                    mb: 2,
                  }}
                >
                  <Typography
                    id={`${sectionId}-books`}
                    component="h3"
                    sx={{ fontSize: 13, fontWeight: 600 }}
                  >
                    {interfaceText('Books & chapters')}
                  </Typography>
                  {readingProgress && (
                    <Typography
                      sx={{
                        fontSize: 12,
                        color: 'text.secondary',
                        fontVariantNumeric: 'tabular-nums',
                      }}
                    >
                      {interfaceText('{{books}} books started · {{chapters}} chapters read', {
                        books: bookStats?.totalBooks || 0,
                        chapters: bookStats?.totalChapters || 0,
                      })}
                    </Typography>
                  )}
                </Box>
                {readingProgress &&
                  (bookStats?.booksWithChapters.length ? (
                    <Box component="ul" sx={{ listStyle: 'none', m: 0, p: 0 }}>
                      {bookStats.booksWithChapters.map((book) => (
                        <Box
                          component="li"
                          key={book.book}
                          sx={{
                            display: 'grid',
                            gridTemplateColumns: { xs: '1fr', sm: '150px minmax(0, 1fr)' },
                            columnGap: 3,
                            rowGap: 1,
                            py: 2,
                            borderTop: 1,
                            borderColor: 'divider',
                          }}
                        >
                          <Box>
                            <Typography sx={{ fontSize: 13, fontWeight: 500 }}>
                              {translateBookName(book.book, t)}
                            </Typography>
                            <Typography sx={{ fontSize: 11, color: 'text.secondary', mt: 0.5 }}>
                              {interfaceText('{{chaptersRead}} chapters read', {
                                chaptersRead: book.chaptersRead,
                              })}
                            </Typography>
                          </Box>
                          <Typography
                            sx={{
                              fontSize: 12,
                              lineHeight: 1.8,
                              color: 'text.secondary',
                              overflowWrap: 'anywhere',
                              fontVariantNumeric: 'tabular-nums',
                            }}
                          >
                            <Box component="span" sx={{ color: 'text.primary' }}>
                              {interfaceText('Chapters')}{' '}
                            </Box>
                            {book.chapters.join(', ')}
                          </Typography>
                        </Box>
                      ))}
                    </Box>
                  ) : (
                    <Typography sx={{ fontSize: 13, color: 'text.secondary', py: 2 }}>
                      {interfaceText('No chapters recorded yet.')}
                    </Typography>
                  ))}
              </Box>
            )}

            {!compact && (
              <Typography
                sx={{
                  mt: 3,
                  pt: 2,
                  borderTop: 1,
                  borderColor: 'divider',
                  fontSize: 12,
                  lineHeight: 1.7,
                  color: 'text.secondary',
                }}
              >
                {interfaceText(
                  'Keep your reading rhythm. Read a chapter today to continue your streak.',
                )}
              </Typography>
            )}
          </>
        )}
      </Box>
    </SubscriptionCheck>
  );
};

export default ReadingStatsPanel;
